"kind": "propose",
"summary": "The api container's CPU limit is too low, causing throttling and readiness probe failures. Increasing the CPU limit to 750m should alleviate the throttling.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Container 'api' is consistently throttled at 0.5 CPU limit (usage 0.495), with 64% throttling ratio, causing readiness probe timeouts.",
    "supporting": ["ev-container_cpu"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "Rollout is not recent (220h ago), so new version is not the cause.",
    "supporting": ["ev-rollout_history"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "node_cpu_contention",
    "summary": "No evidence of node-level CPU contention; throttling occurs at container limit, not node level.",
    "supporting": ["ev-container_cpu"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises CPU limit of 'api' container from 500m to 750m to clear throttling and improve readiness probe success rate.",
  "rationale": "Container is throttled 64% of the time at 0.5 CPU limit (usage 0.495), causing readiness probe timeouts. Raising limit to 750m would provide buffer without over-provisioning.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_recent"]
}
}
